-- ========================================================


function PiecesCollection:__init()
    self.controller = nil

    self.currentPiecesNum = 0
    self.isInit = false -- bool

    self.piecesDatasVO = {}   -- 配表信息: Dictionary: key:pieceId; val:{ isGot, id } 
    self.emotionalPieces = {} --          Dictionary: key:pieceId; val:{ emotionalPiece, isGot, id }
    
    self.rootCanvasCoordinateMatrix = nil -- Matrix4x4

    self.pieceEndTF = nil -- Transform; 碎片被拾取后播放的 特效
end


function PiecesCollection:__delete()
    self.co_1 = nil

    if not isNull(self.co_2) then 
        cs_coroutine.stop(self.co_2)
        self.co_2 = nil
    end
end



function PiecesCollection:Awake()
    if currentInstance == nil then 
        currentInstance = self
    else 
        assert( false, "不允许存在 第二个 RoomActivatorManager 实例" )
    end 
end


---@param isFlexible_ boolean 若为 true, 就算没等到, 也不会报错
function PiecesCollection.WaitInstance( isFlexible_ )
    -- 只等待有限帧
    for i=1,500 do 
        if isNotNull(currentInstance) then 
            break
        end 
        coroutine.yield(Yielders.EndOfFrame)
    end 
    if isFlexible_ ~= true then
        assert( isNotNull(currentInstance), "始终没能等到 PiecesCollection 实例化, 请检查场景" )
    end
end



function PiecesCollection.GetInstance()
    return currentInstance
end


---@param levelId_ integer
function PiecesCollection:SelfInit( levelID_ )
    KTool.SetActive(self.controller.gameObject, true)

    self.transform = self.controller.gameObject.transform
    self.levelID = levelID_


    assert(self.containerTextComp and self.FlySpritePrefab and self.params)
    assert(self.pieceEndTF)
    
    self.jumpUnit = JumpUnit() -- JumpUnit

    -- params ---:
    self.jumpSpeed                     = LuaParametersReader.Read( self.params, "jumpSpeed",                   LuaParametersReader.Type.Float ) -- float FlySprite 跳跃动画参数
    self.jumpHeightweightInSingleScene = LuaParametersReader.Read( self.params, "jumpHeightweightInSingleScene",LuaParametersReader.Type.Float ) -- float FlySprite 跳跃高度权重值: (单场景测试时)
    self.jumpHeightweightInMainProcess = LuaParametersReader.Read( self.params, "jumpHeightweightInMainProcess",LuaParametersReader.Type.Float ) -- float FlySprite 跳跃高度权重值: (主游戏进入时)
    assert( self.jumpSpeed and self.jumpHeightweightInSingleScene and self.jumpHeightweightInMainProcess )

    --self.jumpSpeed = self.jumpSpeed * 2.0

    -- must after Awake()
    self.tgtCamera = DreamSpaceCamera.GetMainCamera()

    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start(self.DelayInit, self)
end



function PiecesCollection:DelayInit() 
    self.isInit = false

    -- 等待一帧
    coroutine.yield(Yielders.EndOfFrame)

    -- 读取配表中全部 碎片数据:
    self.piecesDatasVO = DreamlandUtils.GetAllDreamlandCollectionVoByQuestId( self.levelID )  -- array
    self.totalPiecesNum = table.count(self.piecesDatasVO)

        -- debug:
        local ss = "=== piecesDatasVO ===\n"
        for k,v in pairs(self.piecesDatasVO) do
            ss = ss .. "\n    " ..  tostring(k) .. ", isGot: " .. tostring(v.isGot) .. ", id = " .. v.id
        end 
        print(ss)

    -- 等待所有 EmotionalPiece 调用 piecesCollection:RegisteEmotionalPiece() 
    
    local isAllEmotionalPiecesRegisted = ( self.totalPiecesNum == table.count(self.emotionalPieces) )
    for i=0,300 do 
        if self.totalPiecesNum ~= table.count(self.emotionalPieces) then 
            coroutine.yield(Yielders.EndOfFrame)
        end 
    end 
    -- 检查 配表数据 是否与 场景中 碎片数据 一一吻合:
    assert( self.totalPiecesNum == table.count(self.emotionalPieces), "情绪碎片数量异常; 表中: " .. self.totalPiecesNum .. "; 注册到的: " .. table.count(self.emotionalPieces) )
    ---

    for k,v in pairs(self.piecesDatasVO) do 
        assert( not isNull(self.emotionalPieces[k]), "场景中未找到碎片 pieceId: " .. k )
        -- 顺带填入 id:
        self.emotionalPieces[k].id = v.id
    end


    self:PrintEmotionalPieces()
    

    if checkNumber(DreamSpaceStates.questId) == 0 then 
        printError("koko 异常, questId 异常 = " .. tostring(DreamSpaceStates.questId) )
    end

    -- 读取后端数据, 将已被拾取的 emotionalPiece 隐藏起来:
    local pieceIdsFromServer =  DreamlandUtils.GetHomeDojoPieces( DreamSpaceStates.questId )
    print( "之前已经拾取碎片数量: " .. table.count(pieceIdsFromServer) )
    for k,_pieceId in pairs( pieceIdsFromServer ) do 
        print( "读到服务器 pieceId: " .. tostring(_pieceId) )

        local piece = self.emotionalPieces[ checkNumber(_pieceId) ]
        if not isNull( piece ) then 

            if isNeedPieceAlways == false then
                -- 隐藏 已经拾取的碎片: 
                piece.isGot = true 
                piece.emotionalPiece:SetInactive()
                self.currentPiecesNum = self.currentPiecesNum + 1
            end
        end
    end

    
    ---
    local RoleControllerRootCanvasMgr = import('Game.DreamSpace.UI.RoleControllerRootCanvasMgr'):GetInstance()
    RoleControllerRootCanvasMgr:CheckOrInitSync()
    local parentUICanvas = RoleControllerRootCanvasMgr.dynamicsCanvas
    assert( parentUICanvas )


    --self.jumpHeightweight = DreamSpaceUtils.IsInSingleScene() and self.jumpHeightweightInSingleScene or self.jumpHeightweightInMainProcess
    self.jumpHeightweight = self.jumpHeightweightInMainProcess

    self.jumpHeightweight = 10

    self.FlySprite = Object.Instantiate(self.FlySpritePrefab, parentUICanvas.transform) -- RectTransform
    --self.FlySprite.gameObject:SetActive(false)
    KTool.SetActive( self.FlySprite.gameObject, false )


    self.piecesUIContainerTF = self.containerTextComp.transform



    -- 尝试 N 次, 还是找不到就放弃 情绪碎片 功能了
    for i = 1, DreamSpaceStates.DelayInitWaitFrames do
        local humanCharacter = GlobalsInDreamSpace.FindComponent("humanCharacter") -- Character
        local catCharacter = GlobalsInDreamSpace.FindComponent("catCharacter") -- Character

        if not isNull( humanCharacter ) and not isNull( catCharacter) then

            local humanLua = DreamSpaceLuaUtils.GetLuaScr(humanCharacter.gameObject, "Game.DreamSpace.PiecesCollection.PiecesCollector" )
            local catLua   = DreamSpaceLuaUtils.GetLuaScr(catCharacter.gameObject,   "Game.DreamSpace.PiecesCollection.PiecesCollector" )
            assert( humanLua )
            assert( catLua )

            humanLua.DeliverFunc = function(emotionalPieces_)
                self:Deliver(emotionalPieces_)
            end

            catLua.DeliverFunc   = function(emotionalPieces_)
                self:Deliver(emotionalPieces_)
            end
            break
        end
        coroutine.yield(Yielders.EndOfFrame)
    end


    self:SetContainerText();
    self.rootCanvasCoordinateMatrix = DreamSpaceUtils.RefreshRootCanvasCoordinateMatrix( self.FlySprite )
    -----:
    self.isInit = true
end



