function PiecesCollection:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    DreamSpaceLuaUtils.StopCoroutine( self.co_2 )
    self.co_1 = nil 
    self.co_2 = nil 
    ---
    currentInstance = nil
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --



function PiecesCollection:RegisteEmotionalPiece( emotionalPieces_ )
    self.emotionalPieces[emotionalPieces_.pieceId] = {
        emotionalPiece = emotionalPieces_,
        isGot = false,
        id = nil
    }
end




function PiecesCollection:Deliver(emotionalPieces_)
    DreamSpaceLuaUtils.StopCoroutine( self.co_2 )
    self.co_2 = cs_coroutine.start(function()
        self:Do(emotionalPieces_)
    end) 
end


function PiecesCollection:SetContainerText()
    self.containerTextComp.text = self.currentPiecesNum .. "/" .. self.totalPiecesNum
end


---@param emotionalPiece_ EmotionalPiece
---@return System.Collections.IEnumerator
function PiecesCollection:Do(emotionalPiece_)

    local cachedPiecesNum = self.currentPiecesNum

    cs_coroutine.yield_return( emotionalPiece_:OnTouched( self.pieceEndTF ) )

    self.currentPiecesNum = self.currentPiecesNum + 1
    if self.currentPiecesNum > self.totalPiecesNum then
        printError("采集到的情绪碎片数量 超过了 预定总数, 请检查配置")
    end

    -- 创建
    local newAnchoredPosition = DreamSpaceUtils.CalculateAnchoredPosition(self.tgtCamera, emotionalPiece_.transform.position, 0)
    self.FlySprite.position = DreamSpaceUtils.AnchoredPosition_To_PosWS(newAnchoredPosition, self.rootCanvasCoordinateMatrix)

    --self.FlySprite.gameObject:SetActive(true)
    KTool.SetActive( self.FlySprite.gameObject, true )

    -- FlySprite 抛物线运动到 容器处:
    local initPos = self.FlySprite.position

    self.jumpUnit:ResetState(initPos, self.piecesUIContainerTF.position, Vector3.up, self.jumpSpeed, self.jumpHeightweight)

    while true do
        -- 跳跃:
        local jumpRet, velocity = self.jumpUnit:JumpUpdate() -- float, Vector3
        if jumpRet < 0.0 then
            break
        end

        self.FlySprite.position = self.FlySprite.position + velocity * Time.deltaTime

        coroutine.yield(Yielders.EndOfFrame)
    end
    --self.FlySprite.gameObject:SetActive(false)
    KTool.SetActive( self.FlySprite.gameObject, false )


    -- 更新数据:
    local pieceData = self.emotionalPieces[emotionalPiece_.pieceId]
    -- assert( not isNull(pieceData) and (pieceData.isGot == false) )
    -- pieceData.isGot = true -- 修改数据
    if isNotNull(pieceData) and (pieceData.isGot == false) then 
        pieceData.isGot = true -- 修改数据
    else 
        printError("koko piece 数据异常 pieceData:" .. tostring(pieceData) )
    end 



    self:SetContainerText();
    if self.currentPiecesNum == self.totalPiecesNum then
        self:PlayAllCollectedAnim()
    end 
    -- if self.currentPiecesNum == self.totalPiecesNum then UIAnim


    -- 如果这是第一次捡到碎片, 需要播放剧情:
    if cachedPiecesNum == 0 then 
        if type(PiecesCollectionUtils.OnGetFirstEmotionalPiece) == "function" then 
            PiecesCollectionUtils.OnGetFirstEmotionalPiece()
        end
        --print( "第一次捡到 碎片" )
    end 


end

function PiecesCollection:HidePiecesUIContainer()
    --self.piecesUIContainerTF.gameObject:SetActive(false)
    KTool.SetActive( self.piecesUIContainerTF.gameObject, false )
end



function PiecesCollection:GetCollectedPiecesDatas()

    local ret = {}
    for k,v in pairs(self.emotionalPieces) do 
        assert( v and not isNull(v.emotionalPiece) ) 
        if v.isGot == true then 
            -- 暂不关心 "本次收集的碎片", 而是 "全历史内收集的碎片"
            table.insert( ret, k ) -- 直接存入 pieceId
        end
    end
    -- -- debug:
    -- local ss = "====== 当前已领取到的碎片 num: " .. table.count(ret) .. "======\n";
    -- for k,v in pairs(ret) do 
    --     ss = ss .. "\n   " .. tostring(v)
    -- end
    -- print(ss)
    return ret
end


-- 是否所有碎片 都已收集:
function PiecesCollection:IsAllPiecesCollected()

    local collectedDatas = self:GetCollectedPiecesDatas()
    local collectedNum = table.count(collectedDatas)

    if collectedNum > self.totalPiecesNum then 
        printError( "koko 碎片数据异常 collectedNum = " .. tostring(collectedNum) .. ", totalPiecesNum = " .. tostring(self.totalPiecesNum) )
    end 
    return collectedNum >= self.totalPiecesNum
end



function PiecesCollection:PrintEmotionalPieces()
    local ss = "====== emotionalPieces ======\n";
    for k,v in pairs(self.emotionalPieces) do 
        ss = ss .. "\n   pieceId: " .. k .. ", isGot: " .. tostring(v.isGot) .. ", id: " .. v.id
    end
    print(ss)
end

local allCollectedIconGo = "ActionDreamlandMain_IconFinish_go"

function  PiecesCollection:PlayAllCollectedAnim()
    KTool.SetActive(self.allCollectedIcon, true)
    self.allCollectedIcon:Play(allCollectedIconGo)
    self.countColorSwitch.Status = 2
    DreamSpaceSounds.Play( DreamSpaceSounds.sfx.taskComplete )
end






return PiecesCollection

